const cfg = $('API Keys and Config').first().json;

// Чтобы добавить канал — просто добавь строку в CHANNELS в ноде "API Keys and Config"
// Формат: {"id": "UCxxxxxxx", "name": "Название"}
var channels;
try {
  channels = JSON.parse(cfg.CHANNELS);
} catch(e) {
  throw new Error('CHANNELS must be valid JSON array. Error: ' + e.message);
}

if (!Array.isArray(channels) || channels.length === 0) {
  throw new Error('CHANNELS array is empty. Add at least one channel.');
}

return channels
  .filter(function(ch) { return ch.id && ch.id.trim() !== ''; })
  .map(function(ch) { return { json: {
    channel_id:         ch.id,
    channel_name:       ch.name || ch.id,
    youtube_api_key:    cfg.YOUTUBE_API_KEY,
    openai_api_key:     cfg.OPENAI_API_KEY,
    transcript_lang:    cfg.TRANSCRIPT_LANG || 'ru',
    telegram_chat_id:   cfg.TELEGRAM_CHAT_ID,
    notion_api_key:     cfg.NOTION_API_KEY,
    notion_database_id: cfg.NOTION_DATABASE_ID,
    max_videos:         cfg.MAX_VIDEOS || 10,
    min_score:          cfg.MIN_SCORE || 7,
    claude_model:       cfg.CLAUDE_MODEL,
    published_days_ago: cfg.PUBLISHED_DAYS_AGO || 60
  } }; });

const cfg = $('API Keys and Config').first().json;
const seen = new Set();
const videos = [];

for (const item of $input.all()) {
  const data = item.json;
  if (!Array.isArray(data.items)) continue;
  for (const video of data.items) {
    const id = video.id && video.id.videoId;
    if (!id || seen.has(id)) continue;
    seen.add(id);
    videos.push({ json: {
      videoId:            id,
      title:              video.snippet.title,
      channel:            video.snippet.channelTitle,
      description:        video.snippet.description,
      publishedAt:        video.snippet.publishedAt,
      videoUrl:           'https://www.youtube.com/watch?v=' + id,
      openai_api_key:     cfg.OPENAI_API_KEY,
      transcript_lang:    cfg.TRANSCRIPT_LANG || 'ru',
      telegram_chat_id:   cfg.TELEGRAM_CHAT_ID,
      notion_api_key:     cfg.NOTION_API_KEY,
      notion_database_id: cfg.NOTION_DATABASE_ID,
      min_score:          cfg.MIN_SCORE,
      claude_model:       cfg.CLAUDE_MODEL
    } });
  }
}

if (videos.length === 0) throw new Error('YouTube: видео не найдены. Проверь API Key и квоту.');
return videos;

const cfg = $('API Keys and Config').first().json;

// Читаем уже обработанные Video ID из Notion
const notionResponse = $('Запросить обработанные видео').first().json;
const notionResults = notionResponse.results || [];

const processedIds = new Set(
  notionResults.map(page => {
    try { return page.properties['Video ID'].rich_text[0].plain_text; }
    catch (e) { return null; }
  }).filter(id => id !== null && id !== '')
);

// Все входящие видео (из ноды «Извлечь видео», $input здесь — ответ Notion)
const allItems = $('Извлечь видео').all();

// Оставляем только новые
const newItems = allItems.filter(item => {
  const videoId = item.json.videoId;
  if (!videoId) return false;
  return !processedIds.has(videoId);
});

if (newItems.length === 0) {
  throw new Error(`Новых видео нет. Все ${allItems.length} видео уже обработаны и сохранены в Notion.`);
}

// Сортируем от старых к новым (чтобы обрабатывать в хронологическом порядке)
newItems.sort((a, b) => {
  return new Date(a.json.publishedAt || 0) - new Date(b.json.publishedAt || 0);
});

return newItems.map(item => ({
  json: { ...item.json, NOTION_API_KEY: cfg.NOTION_API_KEY, NOTION_DATABASE_ID: cfg.NOTION_DATABASE_ID }
}));

const resp = $json;
const meta = $('Отфильтровать дубли и сортировать').item.json;

let text = '';

// YouTube timedtext json3 format: { events: [ { segs: [ { utf8: '...' } ] } ] }
if (resp && resp.events && Array.isArray(resp.events)) {
  text = resp.events
    .filter(e => e.segs)
    .map(e => e.segs.map(s => (s.utf8 || '').replace(/\n/g, ' ')).join(''))
    .join(' ')
    .replace(/\s+/g, ' ')
    .trim();
}

if (text.trim().length < 100) {
  // Fallback to description when no subtitles found
  text = meta.description || '';
  if (text.length < 50) return [{ json: { skip: true, reason: 'no_transcript', ...meta } }];
}

if (text.length > 12000) text = text.substring(0, 12000) + '...';

return [{ json: { ...meta, transcript: text, skip: false } }];

const d = $json;
const cfg = $('API Keys and Config').first().json;
const openai_api_key = cfg.OPENAI_API_KEY; // used as anthropic key
const model = d.claude_model || 'claude-haiku-4-5-20251001';
const min_score = d.min_score || 7;

const systemPrompt = `You are an expert business analyst. Extract maximum actionable value from YouTube transcripts for entrepreneurs. Be EXTREMELY specific: include real numbers, exact quotes, step-by-step implementation, specific tool names. Respond ONLY with valid JSON. No markdown, no prose outside JSON. IMPORTANT: ALL text values in the JSON (summary, idea titles, descriptions, impact, implementation steps, key_quotes, metrics, expected_roi, time_to_implement, category names) MUST be written in RUSSIAN language.`;

const userPrompt = `Analyze this YouTube video transcript and extract structured business insights.

VIDEO: ${d.title || ''}
CHANNEL: ${d.channel || ''}
DESCRIPTION: ${(d.description || '').slice(0, 500)}

TRANSCRIPT:
${(d.transcript || '').slice(0, 12000)}

Return JSON with this exact schema (ALL text values in RUSSIAN):
{
  "relevance_score": <1-10>,
  "summary": "<краткое резюме на русском, 3-4 предложения>",
  "key_quotes": ["<цитата из транскрипта>", "<цитата>", "<цитата>"],
  "metrics": ["<конкретное число с контекстом>", "<ещё метрика>"],
  "ideas": [
    {
      "title": "<короткое название на русском, макс 8 слов>",
      "description": "<4-5 предложений на русском: что, почему, какую проблему решает, результат>",
      "category": "<одно из на русском: Рост|Монетизация|Автоматизация|Продукт|Маркетинг|Операции|Контент|Аналитика|AI-инструменты>",
      "impact": "<конкретный эффект с цифрами если есть, на русском>",
      "implementation": ["Шаг 1: <действие>", "Шаг 2: ...", "Шаг 3: ...", "Шаг 4: ...", "Шаг 5: ..."],
      "tools": ["<название инструмента>", "<ещё инструмент>"],
      "difficulty": "<низкая|средняя|высокая>",
      "time_to_implement": "<реалистичная оценка, на русском>",
      "expected_roi": "<ожидаемый результат, на русском>",
      "score": <1-10>
    }
  ]
}

Extract 3-7 ideas. Score ${min_score}+ ideas must be highly actionable with clear ROI. All text in Russian.`;

const body = JSON.stringify({
  model,
  max_tokens: 4096,
  temperature: 0.3,
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user',   content: userPrompt }
  ]
});

return [{ json: { ...d, claude_body: body, openai_api_key } }];

const claudeRaw = $json.content?.[0]?.text ?? $json.choices?.[0]?.message?.content;
if (!claudeRaw) throw new Error('No content in AI response: ' + JSON.stringify($json).slice(0, 300));

const meta = $('Подготовить запрос к Claude').item.json;
const min_score = meta.min_score || 7;

let raw = claudeRaw.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
let analysis;
try {
  analysis = JSON.parse(raw);
} catch(e) {
  const match = raw.match(/\{[\s\S]*\}/);
  if (match) { try { analysis = JSON.parse(match[0]); } catch(e2) { throw new Error('Failed to parse AI JSON: ' + raw.slice(0, 300)); } }
  else throw new Error('No JSON in AI response: ' + raw.slice(0, 300));
}

const ideas = (analysis.ideas || [])
  .filter(i => Number(i.score) >= min_score)
  .sort((a, b) => Number(b.score) - Number(a.score))
  .map(idea => ({
    title:             String(idea.title || ''),
    description:       String(idea.description || ''),
    category:          String(idea.category || ''),
    impact:            String(idea.impact || ''),
    implementation:    Array.isArray(idea.implementation) ? idea.implementation.map(String) : [],
    tools:             Array.isArray(idea.tools) ? idea.tools.map(String) : [],
    difficulty:        String(idea.difficulty || '\u0441\u0440\u0435\u0434\u043d\u044f\u044f'),
    time_to_implement: String(idea.time_to_implement || ''),
    expected_roi:      String(idea.expected_roi || ''),
    score:             Number(idea.score) || 0
  }));

if (ideas.length === 0) {
  return [{ json: { skip: true, reason: 'no_good_ideas', relevance: analysis.relevance_score, ...meta } }];
}

if ((analysis.relevance_score || 0) < min_score) {
  return [{ json: { skip: true, reason: 'low_relevance', score: analysis.relevance_score, ...meta } }];
}

return [{ json: {
  skip:               false,
  videoId:            meta.videoId || '',
  videoUrl:           meta.videoUrl || '',
  title:              meta.title || '',
  channel:            meta.channel || '',
  publishedAt:        meta.publishedAt || '',
  telegram_chat_id:   meta.telegram_chat_id || '',
  NOTION_API_KEY:     meta.NOTION_API_KEY || '',
  NOTION_DATABASE_ID: meta.NOTION_DATABASE_ID || '',
  relevance_score:    Number(analysis.relevance_score) || 0,
  summary:            String(analysis.summary || ''),
  key_quotes:         Array.isArray(analysis.key_quotes) ? analysis.key_quotes : [],
  metrics:            Array.isArray(analysis.metrics) ? analysis.metrics : [],
  ideas,
  ideas_count:        ideas.length
} }];

