={{ (() => {
  function tr(s, n) { var t = String(s || ''); return t.length <= n ? t : t.slice(0, n - 1) + '\u2026'; }

  function p(text) {
    return { object:'block', type:'paragraph', paragraph:{ rich_text:[{ type:'text', text:{ content: tr(text, 2000) } }] } };
  }
  function h2(text) {
    return { object:'block', type:'heading_2', heading_2:{ rich_text:[{ type:'text', text:{ content: tr(text, 2000) } }] } };
  }
  function h3(text) {
    return { object:'block', type:'heading_3', heading_3:{ rich_text:[{ type:'text', text:{ content: tr(text, 2000) } }] } };
  }
  function bullet(text) {
    return { object:'block', type:'bulleted_list_item', bulleted_list_item:{ rich_text:[{ type:'text', text:{ content: tr(text, 2000) } }] } };
  }
  function numbered(text) {
    return { object:'block', type:'numbered_list_item', numbered_list_item:{ rich_text:[{ type:'text', text:{ content: tr(text, 2000) } }] } };
  }
  function quote(text) {
    return { object:'block', type:'quote', quote:{ rich_text:[{ type:'text', text:{ content: tr(text, 2000) } }] } };
  }
  function divider() {
    return { object:'block', type:'divider', divider:{} };
  }

  var cfg    = $('API Keys and Config').first().json;
  var ideas  = Array.isArray($json.ideas)      ? $json.ideas      : [];
  var quotes = Array.isArray($json.key_quotes) ? $json.key_quotes : [];
  var metrics= Array.isArray($json.metrics)    ? $json.metrics    : [];

  var notionDate;
  try { notionDate = new Date($json.publishedAt).toISOString().split('T')[0]; }
  catch(e) { notionDate = new Date().toISOString().split('T')[0]; }

  var children = [];

  // О чём видео
  if ($json.summary) {
    children.push(h2('\uD83D\uDCDD \u041E \u0447\u0451\u043c \u0432\u0438\u0434\u0435\u043e'));
    children.push(p($json.summary));
  }

  // Ключевые цитаты
  if (quotes.length > 0) {
    children.push(divider());
    children.push(h2('\uD83D\uDDE3 \u041A\u043B\u044E\u0447\u0435\u0432\u044B\u0435 \u0446\u0438\u0442\u0430\u0442\u044B'));
    quotes.forEach(function(q) { children.push(quote(q)); });
  }

  // Ключевые цифры
  if (metrics.length > 0) {
    children.push(divider());
    children.push(h2('\uD83D\uDCCA \u0426\u0438\u0444\u0440\u044B \u0438 \u0444\u0430\u043A\u0442\u044B'));
    metrics.forEach(function(m) { children.push(bullet(m)); });
  }

  // Идеи
  if (ideas.length > 0) {
    children.push(divider());
    children.push(h2('\uD83D\uDCA1 \u0418\u0434\u0435\u0438 \u0438 \u0438\u043D\u0441\u0430\u0439\u0442\u044B'));

    ideas.forEach(function(idea, i) {
      var score = idea.score ? ' \u2B50' + idea.score + '/10' : '';
      var cat   = idea.category ? ' [' + idea.category + ']' : '';
      children.push(h3((i + 1) + '. ' + idea.title + cat + score));

      if (idea.description) { children.push(p(idea.description)); }

      if (idea.impact)            { children.push(bullet('\uD83C\uDFAF \u042D\u0444\u0444\u0435\u043A\u0442: '       + idea.impact)); }
      if (idea.expected_roi)      { children.push(bullet('\uD83D\uDCB0 ROI: '                                              + idea.expected_roi)); }
      if (idea.time_to_implement) { children.push(bullet('\u23F1 \u0421\u0440\u043E\u043A: '                           + idea.time_to_implement)); }
      if (idea.difficulty)        { children.push(bullet('\uD83D\uDD27 \u0421\u043B\u043E\u0436\u043D\u043E\u0441\u0442\u044C: ' + idea.difficulty)); }

      if (Array.isArray(idea.implementation) && idea.implementation.length > 0) {
        children.push(p('\uD83D\uDCCB \u041A\u0430\u043A \u0440\u0435\u0430\u043B\u0438\u0437\u043E\u0432\u0430\u0442\u044C:'));
        idea.implementation.forEach(function(step) { children.push(numbered(step)); });
      }

      if (Array.isArray(idea.tools) && idea.tools.length > 0) {
        children.push(bullet('\uD83D\uDEE0 \u0418\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442\u044B: ' + idea.tools.join(', ')));
      }
    });
  }

  // Ссылка на видео
  if ($json.videoUrl) {
    children.push(divider());
    children.push(p('\uD83D\uDD17 ' + $json.videoUrl));
  }

  var body = {
    parent: { database_id: cfg.NOTION_DATABASE_ID },
    properties: {
      'Name':        { title:     [{ text: { content: tr($json.title, 200) } }] },
      'Date':        { date:      { start: notionDate } },
      'Status':      { status:    { name: 'In progress' } },
      'Video ID':    { rich_text: [{ text: { content: tr($json.videoId, 200) } }] },
      'Channel':     { rich_text: [{ text: { content: tr($json.channel, 200) } }] },
      'Ideas_count': { number: Number($json.ideas_count) || 0 }
    },
    children: children.slice(0, 95)
  };

  return JSON.stringify(body);
})() }}

