const allItems = $input.all();
if (allItems.length === 0) throw new Error('No items received by digest formatter.');

const chat_id = allItems[0].json.telegram_chat_id || allItems[0].json.chat_id || '';

function esc(str) {
  return String(str || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}

function formatDate(iso) {
  if (!iso) return '';
  try {
    return new Date(iso).toLocaleDateString('ru-RU', { day:'numeric', month:'long', year:'numeric' });
  } catch(e) { return iso; }
}

function splitChunks(text, maxLen) {
  const chunks = [];
  let remaining = text;
  while (remaining.length > maxLen) {
    let splitAt = remaining.lastIndexOf('\n\n', maxLen);
    if (splitAt < maxLen * 0.5) splitAt = remaining.lastIndexOf('\n', maxLen);
    if (splitAt < maxLen * 0.5) splitAt = maxLen;
    chunks.push(remaining.slice(0, splitAt).trim());
    remaining = remaining.slice(splitAt).trim();
  }
  if (remaining.length > 0) chunks.push(remaining);
  return chunks;
}

const totalVideos = allItems.length;
const totalIdeas  = allItems.reduce((acc, i) => acc + (i.json.ideas || []).length, 0);

// ── Шапка ────────────────────────────────────────────────────────────────────
let digest = '<b>YouTube Ideas Digest</b>\n';
digest += '\uD83D\uDCC5 ' + formatDate(new Date().toISOString()) + '\n';
digest += '\uD83C\uDFA5 ' + totalVideos + ' \u0432\u0438\u0434\u0435\u043e';
digest += '   \uD83D\uDCA1 ' + totalIdeas + ' \u0438\u0434\u0435\u0439\n';

// ── Секция по каждому видео ───────────────────────────────────────────────────
allItems.forEach((item, idx) => {
  const v = item.json;
  const ideas = Array.isArray(v.ideas) ? v.ideas : [];
  const score = v.relevance_score || 0;

  digest += '\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n';

  // Заголовок
  const titleStr = v.videoUrl
    ? '<a href="' + esc(v.videoUrl) + '">' + esc(v.title) + '</a>'
    : '<b>' + esc(v.title) + '</b>';
  digest += '\uD83C\uDFA5 ' + titleStr + '\n';
  digest += '\uD83D\uDCFA ' + esc(v.channel);
  if (v.publishedAt) digest += '   \uD83D\uDCC5 ' + formatDate(v.publishedAt);
  digest += '   \u2B50 ' + score + '/10\n';

  // О чём видео
  if (v.summary) {
    digest += '\n\uD83D\uDCDD <b>\u041e \u0447\u0451\u043c \u0432\u0438\u0434\u0435\u043e:</b>\n';
    digest += esc(v.summary) + '\n';
  }

  // Основные мысли — тезисно (заголовки идей)
  if (ideas.length > 0) {
    digest += '\n\uD83D\uDCA1 <b>\u041e\u0441\u043d\u043e\u0432\u043d\u044b\u0435 \u043c\u044b\u0441\u043b\u0438:</b>\n';
    ideas.forEach(idea => {
      digest += '\u2022 <b>' + esc(idea.title) + '</b>\n';
      if (idea.description) {
        digest += '   ' + esc(idea.description) + '\n';
      }
    });
  }

  // Как реализовать — шаги из всех идей объединяем
  const allSteps = [];
  ideas.forEach(idea => {
    if (Array.isArray(idea.implementation)) {
      idea.implementation.forEach(step => allSteps.push(step));
    }
  });
  if (allSteps.length > 0) {
    digest += '\n\uD83D\uDEE0 <b>\u041A\u0430\u043A \u0440\u0435\u0430\u043B\u0438\u0437\u043E\u0432\u0430\u0442\u044C:</b>\n';
    // Показываем до 7 шагов чтобы не перегружать
    allSteps.slice(0, 7).forEach(step => {
      digest += '\u2022 ' + esc(step) + '\n';
    });
  }

  // Инструменты
  const allTools = [];
  ideas.forEach(idea => {
    if (Array.isArray(idea.tools)) {
      idea.tools.forEach(t => { if (!allTools.includes(t)) allTools.push(t); });
    }
  });
  if (allTools.length > 0) {
    digest += '\n\uD83D\uDD27 <b>\u0418\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442\u044B:</b> ' + esc(allTools.join(', ')) + '\n';
  }
});

// ── Источники ────────────────────────────────────────────────────────────────
digest += '\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n';
digest += '\uD83D\uDCCC <b>\u0418\u0441\u0442\u043E\u0447\u043D\u0438\u043A\u0438:</b>\n';
allItems.forEach((item, i) => {
  const v = item.json;
  const link = v.videoUrl
    ? '<a href="' + esc(v.videoUrl) + '">' + esc(v.title) + '</a>'
    : esc(v.title);
  digest += (i + 1) + '. ' + link + ' \u2014 ' + esc(v.channel) + '\n';
});

// ── Разбить на куски ≤4000 символов ─────────────────────────────────────────
const chunks = splitChunks(digest, 4000);
return chunks.map((chunk, i) => ({
  json: {
    chat_id,
    message: chunk,
    text:    chunk,
    parse_mode: 'HTML',
    disable_web_page_preview: true,
    chunk_index:  i + 1,
    total_chunks: chunks.length
  }
}));
